mapper.insert:
INSERT INTO auth_session (
    session_id, user_id, token_hash, expires_at, created_at
) VALUES (
    #{sessionId}, #{userId}, #{tokenHash}, #{expiresAt}, #{createdAt}
)

mapper.select:
SELECT session_id, user_id, token_hash, expires_at, revoked_at, created_at
FROM auth_session
WHERE token_hash = #{tokenHash}
  AND revoked_at IS NULL
  AND expires_at > #{now}

mapper.update:
UPDATE auth_session
SET revoked_at = #{revokedAt}
WHERE session_id = #{sessionId}
  AND revoked_at IS NULL
